css:
:root{
  /* 색 견본 — 071739 4B6382 A4B5C4 CDD5DB A68868 E3C39D
     밝은 쪽(c0)에서 진한 쪽(c6)으로 7단계. 다크모드는 이 단계를 뒤집는다. */
  --c0:#ffffff; --c1:#f3f7fa; --c2:#e4ebf1; --c3:#cdd5db; --c4:#8ea3b6; --c5:#4b6382; --c6:#071739;
  --on-solid:#ffffff;
  --bg1:#e8edf2; --bg2:#cdd5db; --card:var(--c0); --line:var(--c2); --line2:var(--c1);
  --ink:#071739; --ink2:#3c5171; --ink3:#4b6382;
  --navy:#071739; --accent:#8a6238; --accent2:#f6ead9; --accent-solid:#e3c39d; --on-accent:#071739;
  --s-blue:#2f5da8;  --t-blue:#e7eefa;
  --s-green:#0f7a55; --t-green:#e2f4ec;
  --s-red:#b0344c;   --t-red:#fceaee;
  --s-amber:#96631a; --t-amber:#faefdd;
  --s-violet:#6b46c1;--t-violet:#f0ecfb;
  --s-lime:#4d7c22;  --t-lime:#eef5e2;
  --s-teal:#0e7490;  --t-teal:#e2f2f6;
  /* 등급 6단계 (screen-design.md §3-1). 의미색을 참조만 하므로 다크 블록이
     의미색을 덮으면 자동으로 따라간다. 빨강은 경고에 배정돼 있어 등급에 쓰지 않는다.
     미판정 0 은 회색 — 색을 주면 낮은 등급처럼 읽힌다. 판정을 못 한 것이지 낮은 게 아니다. */
  --g6s:var(--s-violet); --g6t:var(--t-violet);
  --g5s:var(--s-blue);   --g5t:var(--t-blue);
  --g4s:var(--s-teal);   --g4t:var(--t-teal);
  --g3s:var(--s-green);  --g3t:var(--t-green);
  --g2s:var(--s-lime);   --g2t:var(--t-lime);
  --g1s:var(--s-amber);  --g1t:var(--t-amber);
  --g0s:var(--ink3);     --g0t:var(--c1);
  --green:var(--s-green); --blue:var(--s-blue); --violet:var(--s-violet);
  --amber:var(--s-amber); --rose:var(--s-red);
  --ui:'Gothic A1','Pretendard','Apple SD Gothic Neo',system-ui,sans-serif;
  --num:'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,monospace;
  --S:#071739; --A:#4b6382; --B:#a4b5c4; --C:#cdd5db; --K:#a68868; --U:#e4ebf1;
  --r:16px; --sh:0 4px 18px rgba(7,23,57,.07); --sh2:0 10px 34px rgba(7,23,57,.14);
  --shl:0 6px 16px rgba(7,23,57,.28);
  --veil16:rgba(255,255,255,.16);
  --veil18:rgba(255,255,255,.18);
  --veil22:rgba(255,255,255,.22);
  --veil62:rgba(255,255,255,.62);
  --sel-bg:#071739; --sel-fg:#ffffff; --sel-bd:#071739;
  --info-bg:rgba(227,195,157,.17); --info-bd:rgba(166,136,104,.34); --info-ac:#c9a678;
  --pl-ac:#1d4ed8; --pl-hot:#2563eb; --pl-edge:#6d88ad; --pl-edge2:rgba(29,78,216,.24);
  --pl-top:#2f6fd0; --pl-lf:#5b86c4; --pl-rt:#2c4f80; --pl-plate:#d5e1f2;
  --pl-dot:#2563eb; --pl-stage:rgba(59,130,246,.05);
  --u1:#dc2626; --u2:#2563eb; --u3:#4338ca; --u4:#db2777; --u5:#047857; --u6:#7c3aed; --u7:#b45309;
  --u0:#64748b; --grid:#d5deea;
  --num-bg:rgba(15,122,85,.09); --num-bd:rgba(15,122,85,.24); --num-fg:#0b6647;
  color-scheme:light;
}
/* 다크 — 배경 071739, 글씨 CDD5DB, 강조 E3C39D */
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]) .rail .logo .lgl{display:none}
:root:not([data-theme="light"]) .rail .logo .lgd{display:block}
:root:not([data-theme="light"]){
  --c0:#0c2149; --c1:#102a58; --c2:#1c3a6b; --c3:#2f4d7d; --c4:#7d93ad; --c5:#a4b5c4; --c6:#cdd5db;
  --on-solid:#071739;
  --bg1:#071739; --bg2:#0a1d44;
  --ink:#cdd5db; --ink2:#a4b5c4; --ink3:#93a7bd;
  --navy:#cdd5db; --accent:#e3c39d; --accent2:#3a2b1a; --accent-solid:#e3c39d; --on-accent:#071739;
  --s-blue:#8fb4e8;  --t-blue:#12305e;
  --s-green:#6fd6ac; --t-green:#0d3a2c;
  --s-red:#f0a0ae;   --t-red:#3f1a26;
  --s-amber:#e8c37a; --t-amber:#3b2a10;
  --s-violet:#c2a9f0;--t-violet:#2a1e4d;
  --s-lime:#a8d47a;  --t-lime:#20340f;
  --s-teal:#6ec6da;  --t-teal:#0d3541;
  --S:#cdd5db; --A:#a4b5c4; --B:#4b6382; --C:#2f4d7d; --K:#e3c39d; --U:#1c3a6b;
  --sh:0 4px 18px rgba(0,0,0,.34); --sh2:0 10px 34px rgba(0,0,0,.46);
  --shl:0 6px 16px rgba(0,0,0,.5);
  --veil16:rgba(205,213,219,.16);
  --veil18:rgba(205,213,219,.18);
  --veil22:rgba(205,213,219,.22);
  --veil62:rgba(16,42,88,.62);
  --sel-bg:#1c3a6b; --sel-fg:#cdd5db; --sel-bd:#e3c39d;
  --info-bg:rgba(227,195,157,.10); --info-bd:rgba(227,195,157,.26); --info-ac:#e3c39d;
  --pl-ac:#7dd3fc; --pl-hot:#cfe8ff; --pl-edge:#4a6fa5; --pl-edge2:rgba(96,165,250,.22);
  --pl-top:#7fb2ff; --pl-lf:#1e3a6e; --pl-rt:#0d1c38; --pl-plate:#0a1730;
  --pl-dot:#7dd3fc; --pl-stage:rgba(96,165,250,.06);
  --u1:#f87171; --u2:#60a5fa; --u3:#a5b4fc; --u4:#f472b6; --u5:#34d399; --u6:#c4b5fd; --u7:#fbbf24;
  --u0:#94a3b8; --grid:#1b3462;
  --num-bg:rgba(111,214,172,.11); --num-bd:rgba(111,214,172,.26); --num-fg:#8fe0be;
  color-scheme:dark;
}}
[data-theme="dark"] .rail .logo .lgl{display:none}
[data-theme="dark"] .rail .logo .lgd{display:block}
[data-theme="dark"]{
  --c0:#0c2149; --c1:#102a58; --c2:#1c3a6b; --c3:#2f4d7d; --c4:#7d93ad; --c5:#a4b5c4; --c6:#cdd5db;
  --on-solid:#071739;
  --bg1:#071739; --bg2:#0a1d44;
  --ink:#cdd5db; --ink2:#a4b5c4; --ink3:#93a7bd;
  --navy:#cdd5db; --accent:#e3c39d; --accent2:#3a2b1a; --accent-solid:#e3c39d; --on-accent:#071739;
  --s-blue:#8fb4e8;  --t-blue:#12305e;
  --s-green:#6fd6ac; --t-green:#0d3a2c;
  --s-red:#f0a0ae;   --t-red:#3f1a26;
  --s-amber:#e8c37a; --t-amber:#3b2a10;
  --s-violet:#c2a9f0;--t-violet:#2a1e4d;
  --s-lime:#a8d47a;  --t-lime:#20340f;
  --s-teal:#6ec6da;  --t-teal:#0d3541;
  --S:#cdd5db; --A:#a4b5c4; --B:#4b6382; --C:#2f4d7d; --K:#e3c39d; --U:#1c3a6b;
  --sh:0 4px 18px rgba(0,0,0,.34); --sh2:0 10px 34px rgba(0,0,0,.46);
  --shl:0 6px 16px rgba(0,0,0,.5);
  --veil16:rgba(205,213,219,.16);
  --veil18:rgba(205,213,219,.18);
  --veil22:rgba(205,213,219,.22);
  --veil62:rgba(16,42,88,.62);
  --sel-bg:#1c3a6b; --sel-fg:#cdd5db; --sel-bd:#e3c39d;
  --info-bg:rgba(227,195,157,.10); --info-bd:rgba(227,195,157,.26); --info-ac:#e3c39d;
  --pl-ac:#7dd3fc; --pl-hot:#cfe8ff; --pl-edge:#4a6fa5; --pl-edge2:rgba(96,165,250,.22);
  --pl-top:#7fb2ff; --pl-lf:#1e3a6e; --pl-rt:#0d1c38; --pl-plate:#0a1730;
  --pl-dot:#7dd3fc; --pl-stage:rgba(96,165,250,.06);
  --u1:#f87171; --u2:#60a5fa; --u3:#a5b4fc; --u4:#f472b6; --u5:#34d399; --u6:#c4b5fd; --u7:#fbbf24;
  --u0:#94a3b8; --grid:#1b3462;
  --num-bg:rgba(111,214,172,.11); --num-bd:rgba(111,214,172,.26); --num-fg:#8fe0be;
  color-scheme:dark;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font:400 13.5px/1.55 var(--ui);letter-spacing:-.1px;
  color:var(--ink);background:linear-gradient(158deg,var(--bg1),var(--bg2));background-attachment:fixed;-webkit-font-smoothing:antialiased}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:8px}
@media(prefers-reduced-motion:reduce){*{transition:none !important;animation:none !important}}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer}
::-webkit-scrollbar{width:9px;height:9px}
::-webkit-scrollbar-thumb{background:var(--s-blue);border-radius:9px;border:2px solid transparent;background-clip:content-box}
::-webkit-scrollbar-track{background:transparent}

.app{display:flex;height:100vh;overflow:hidden}
/* ── 좌측 레일 ── */
.rail{width:92px;flex:0 0 92px;display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px 7px}
.rail .logo{width:46px;height:46px;margin-bottom:14px;display:grid;place-content:center}
.rail .logo img{width:46px;height:46px;object-fit:contain;display:block}
.rail .logo .lgd{display:none}
/* 성과관리 — 분야 협력 탐색과 같은 무게로 눈에 띄게 */
.rail button.hero2{color:var(--accent);background:var(--accent2);box-shadow:inset 0 0 0 1px var(--accent-solid)}
.rail button.hero2 i{font-size:19px}
.rail button.hero2:hover{background:var(--accent-solid);color:var(--on-accent)}
.rail button.hero2.on{background:var(--accent-solid);color:var(--on-accent);box-shadow:var(--shl)}
.rail button.thm{color:var(--ink3);opacity:.85}
.rail button.thm:hover{opacity:1}
.rail button{width:100%;padding:8px 2px 7px;border-radius:12px;display:flex;flex-direction:column;align-items:center;gap:3px;
 color:var(--ink3);transition:.15s;line-height:1.2}
.rail button i{font-style:normal;font-size:17px;line-height:1}
.rail button span{font:700 11px/1.25 var(--ui);text-align:center;letter-spacing:-.01em}
.rail button:hover{background:var(--c0);color:var(--ink);box-shadow:var(--sh)}
.rail button.soon{opacity:.32;cursor:not-allowed;position:relative}
.rail button.soon:hover{background:none;box-shadow:none;color:var(--ink3)}
.rail button.soon::after{content:'';position:absolute;top:7px;right:9px;width:5px;height:5px;border-radius:50%;background:var(--s-blue)}
.rail button.on{background:var(--sel-bg);color:var(--sel-fg);box-shadow:var(--shl)}
.rail button.hero{color:var(--accent);background:var(--c1);box-shadow:inset 0 0 0 1px var(--t-amber)}
.rail button.hero i{font-size:19px}
.rail button.hero:hover{background:var(--t-amber);color:var(--s-amber)}
.rail button.hero.on{background:var(--accent);color:var(--on-solid);box-shadow:0 6px 18px rgba(242,104,60,.42)}
.rail button.hero::after{content:'NEW';position:absolute;top:3px;right:5px;font:800 7px var(--ui);color:var(--accent);letter-spacing:.04em}
.rail button.hero.on::after{color:var(--on-solid)}
.rail button{position:relative}
.rail .sp{flex:1}

.main{flex:1;min-width:0;display:flex;flex-direction:column;padding:16px 18px 16px 0;gap:14px}

/* ── 헤더 ── */
.top{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.top h1{margin:0;font-size:22px;font-weight:800;letter-spacing:-.7px;text-wrap:balance}
.top .sub{font-size:13px;color:var(--ink3);margin-top:2px}
.search{flex:1;min-width:200px;max-width:420px;display:flex;align-items:center;gap:9px;background:var(--c0);border:1px solid var(--line);border-radius:999px;padding:9px 16px;box-shadow:var(--sh)}
.search input{border:0;outline:0;flex:1;background:none;font:inherit}
.seg{display:flex;background:var(--c0);border:1px solid var(--line);border-radius:999px;padding:3px;box-shadow:var(--sh)}
.seg button{padding:6px 14px;border-radius:999px;font-size:13px;font-weight:600;color:var(--ink2)}
.seg button.on{background:var(--navy);color:var(--on-solid)}
.btn-a{background:var(--accent);color:var(--on-solid);padding:10px 18px;border-radius:999px;font-weight:700;font-size:13px;box-shadow:0 6px 16px rgba(242,104,60,.32)}

/* ── KPI ── */
.kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:11px}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:13px 15px;box-shadow:var(--sh);position:relative;overflow:hidden}
.kpi .lb{font-size:12px;color:var(--ink3);font-weight:600;letter-spacing:.1px}
.kpi .vl{font:600 26px/1.1 var(--num);letter-spacing:-1.2px;margin-top:4px;font-variant-numeric:tabular-nums}
.kpi .vl small{font:500 12px var(--ui);color:var(--ink3);margin-left:4px;letter-spacing:0}
.kpi .dt{font-size:12px;color:var(--ink3);margin-top:3px;font-variant-numeric:tabular-nums}
.kpi::after{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--c,var(--c2))}
.kpi.k-alert{background:linear-gradient(90deg,var(--c1),var(--c0) 46%)}
.kpi.k-warn{background:linear-gradient(90deg,var(--c1),var(--c0) 46%)}

/* ── 본문 2단 ── */
.split{flex:1;min-height:0;display:grid;grid-template-columns:326px minmax(0,1fr);gap:14px}
.pane{max-width:100%;background:var(--veil62);border:1px solid var(--c0);border-radius:20px;padding:12px;display:flex;flex-direction:column;min-height:0;box-shadow:var(--sh)}
.pane>.ph{display:flex;align-items:center;gap:8px;padding:4px 6px 10px;flex-shrink:0}
.pane>.ph b{font-size:15px;font-weight:800;letter-spacing:-.4px}
.pane>.ph .cnt{font-size:12px;color:var(--ink3);font-weight:600}
.scroll{overflow:auto;flex:1;min-height:0;padding-right:3px}

/* ── 학과 카드 ── */
.dcard{background:var(--c0);border:1px solid var(--line);border-radius:14px;padding:12px 13px;margin-bottom:9px;cursor:pointer;transition:.14s;position:relative}
.dcard:hover{transform:translateY(-1px);box-shadow:var(--sh2);border-color:var(--t-blue)}
.dcard.on{background:var(--sel-bg);border-color:var(--sel-bd);box-shadow:var(--sh2)}
.dcard.on *{color:var(--sel-fg) !important}
.dcard.on .bar{background:var(--veil22)}
.dcard.on .gy{background:var(--veil18) !important;color:var(--sel-fg) !important}

.dcard .nm{font-weight:700;font-size:13.5px;display:flex;align-items:center;gap:6px}
.dcard .gy{font-size:12px;font-weight:700;padding:1.5px 7px;border-radius:999px;background:var(--c1);color:var(--ink2)}
.dcard.g이공 .gy{background:var(--t-blue);color:var(--s-blue)}
.dcard.g의약생명 .gy{background:var(--t-green);color:var(--s-green)}
.dcard.g인문사회 .gy{background:var(--t-violet);color:var(--s-violet)}
.dcard .mt{display:flex;gap:12px;margin-top:7px;font-size:12px;color:var(--ink2)}
.dcard .mt b{color:var(--ink);font:600 13px var(--num);font-variant-numeric:tabular-nums}
.bar{height:5px;border-radius:99px;background:var(--c1);margin-top:9px;overflow:hidden}
.bar i{display:block;height:100%;border-radius:99px;background:var(--green)}
.dcard .rv{position:absolute;top:11px;right:11px;font-size:12px;font-weight:700;color:var(--rose);background:var(--t-red);border:1px solid var(--t-red);border-radius:999px;padding:1px 7px}
.dcard.on .rv{background:var(--veil16);border-color:transparent;color:var(--sel-fg) !important}

/* ── 우측: 통계 스트립 ── */
.dcap{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:700;color:var(--ink3);margin:0 2px 8px;flex-shrink:0}
.dcap b{color:var(--ink);font-size:13px;letter-spacing:-.3px}
.dcap i{flex:1;height:1px;background:var(--line);display:block}
.dkpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:11px;margin-bottom:11px;flex-shrink:0}
.dkpis .kpi{padding:11px 14px}
.dkpis .kpi .vl{font-size:23px}
@media(max-width:1400px){.dkpis{grid-template-columns:repeat(3,minmax(0,1fr))}}
.stat{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,.82fr) minmax(0,1fr);gap:11px;margin-bottom:11px;flex-shrink:0}
.sc{background:var(--c0);border:1px solid var(--line);border-radius:14px;padding:12px 14px;box-shadow:var(--sh)}
.sc h4{margin:0 0 9px;font-size:12px;font-weight:700;color:var(--ink3);letter-spacing:.2px}
.ybar{display:flex;align-items:flex-end;gap:6px;height:92px;padding-top:6px}
.ybar>div{flex:1;display:flex;flex-direction:column;align-items:center;gap:5px}
.ybar i{width:100%;display:flex;flex-direction:column;border-radius:5px 5px 2px 2px;overflow:hidden;min-height:3px;background:var(--line2);transition:.15s}
.ybar i em{display:block;width:100%}
.ybar>div:hover i{filter:brightness(1.06)}
.ybar span{font:600 9.5px var(--num);color:var(--ink3);font-variant-numeric:tabular-nums;text-align:center;line-height:1.25}
.ybar span u{display:block;text-decoration:none;font:600 8.5px var(--ui);color:var(--s-amber);letter-spacing:-.2px}
.ymeta{margin-top:11px;padding-top:10px;border-top:1px solid var(--line2);font-size:12px;color:var(--ink3);line-height:1.5}
/* 집계 주의 박스 */
.qrow{display:flex;align-items:baseline;gap:8px;padding:7px 0;border-bottom:1px solid var(--line2)}
.qrow:last-of-type{border-bottom:0}
.qrow .ql{flex:1;min-width:0}
.qrow .ql b{display:block;font-size:12px;font-weight:700;color:var(--ink)}
.qrow .ql i{display:block;font-style:normal;font-size:11px;color:var(--ink3);margin-top:1px;line-height:1.35}
.qrow .qv{font:600 15px var(--num);letter-spacing:-.5px;font-variant-numeric:tabular-nums;white-space:nowrap}
.qrow .qv small{font:600 11px var(--ui);color:var(--ink3);margin-left:2px}
.qrow.q-warn .qv{color:var(--s-amber)}
.ymeta b{color:var(--ink2)}
/* 저자 역할 분포 */
.rsb{display:flex;height:9px;border-radius:5px;overflow:hidden;background:var(--c1)}
.rsb i{height:100%}
.rlg{display:flex;flex-wrap:wrap;gap:9px;margin-top:8px;font-size:12px;color:var(--ink2)}
.rlg i{display:inline-block;width:7px;height:7px;border-radius:2px;margin-right:4px;vertical-align:middle}
.rsum{display:flex;gap:12px;margin-top:12px;padding-top:11px;border-top:1px solid var(--line2)}
.rsum>div{flex:1}
.rsum .l{font-size:12px;color:var(--ink3);font-weight:600}
.rsum .n{font:600 16px var(--num);letter-spacing:-.5px;margin-top:2px;font-variant-numeric:tabular-nums}
.rsum .n small{font:600 12px var(--ui);color:var(--ink3)}
.stk{display:flex;height:11px;border-radius:99px;overflow:hidden;background:var(--c1)}
.stk i{display:block;height:100%}
.lg{display:flex;flex-wrap:wrap;gap:9px;margin-top:9px;font-size:12px;color:var(--ink2)}
.lg em{width:8px;height:8px;border-radius:3px;display:inline-block;margin-right:4px}
.ifrow{display:flex;justify-content:space-between;align-items:center;font-size:12px;padding:3px 0}
.ifrow b{font:600 13px var(--num);font-variant-numeric:tabular-nums;min-width:44px;text-align:right}
.mini{height:5px;border-radius:99px;background:var(--c1);flex:1;margin:0 9px;overflow:hidden}
.mini i{display:block;height:100%;border-radius:99px}

/* ── 트리 ── */
.tree{background:var(--c0);border:1px solid var(--line);border-radius:16px;flex:1;min-height:0;display:flex;flex-direction:column;box-shadow:var(--sh);overflow:hidden}
.th{display:flex;align-items:center;gap:10px;padding:11px 15px;border-bottom:1px solid var(--line2);flex-shrink:0;flex-wrap:wrap}
.th b{font-size:15px;font-weight:800;letter-spacing:-.4px}
.chip{font-size:12px;font-weight:600;color:var(--ink2);background:var(--c1);border:1px solid var(--line);border-radius:999px;padding:3px 10px}
.chip.on{background:var(--navy);color:var(--on-solid);border-color:var(--navy)}
.tb{overflow:auto;flex:1;min-height:0}

.row{display:flex;align-items:center;gap:10px;padding:8px 15px;border-bottom:1px solid var(--line2);cursor:pointer;transition:.1s}
.row:hover{background:var(--c1)}
.row.lv1{background:var(--c0)}
.row.lv2{padding-left:44px;background:var(--c0)}
.row.open{background:var(--c1)}
.tw{width:15px;flex-shrink:0;color:var(--ink3);font-size:11px;transition:.15s;text-align:center}
.tw.op{transform:rotate(90deg)}
.av{width:28px;height:28px;border-radius:9px;flex-shrink:0;display:grid;place-items:center;font-size:12px;font-weight:700;color:var(--on-solid);letter-spacing:-.3px}
.av.p{background:linear-gradient(140deg,var(--s-blue),var(--s-blue))} .av.j{background:linear-gradient(140deg,var(--s-lime),var(--s-amber))}
.av.s{background:linear-gradient(140deg,var(--s-green),var(--s-green))}
.nmw{flex:1;min-width:0}
.nmw .n1{font-weight:700;font-size:13px;display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nmw .n2{font-size:12px;color:var(--ink3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bd{font-size:11px;font-weight:700;padding:1.5px 7px;border-radius:999px;flex-shrink:0}
.bd.p{background:var(--t-blue);color:var(--s-blue)} .bd.j{background:var(--t-lime);color:var(--s-amber)} .bd.s{background:var(--t-green);color:var(--s-green)}
.bd.l{background:var(--t-violet);color:var(--s-violet)} .bd.n{background:var(--c1);color:var(--s-blue);font-weight:600}
.wbadge{font-size:11px;font-weight:700;padding:1.5px 7px;border-radius:999px;background:var(--t-red);color:var(--rose);flex-shrink:0}
.via{font-size:11px;font-weight:600;padding:1.5px 7px;border-radius:999px;background:var(--t-violet);color:var(--s-violet);flex-shrink:0}
.mx{display:flex;align-items:center;gap:18px;flex-shrink:0;text-align:right}
.mx .m{min-width:52px}
.mx .m .v{font:600 14px var(--num);letter-spacing:-.5px;line-height:1.15;font-variant-numeric:tabular-nums}
.mx .m .k{font-size:11px;color:var(--ink3);font-weight:600;margin-top:1px}
.mx .m .v.z{color:var(--s-blue)}
.mx .m.mut .v{color:var(--ink3)}
.mx .m.s10 .v{color:var(--S)}
/* IF 등급 막대 */
.tb-w{width:118px;flex:none}
.tbar{display:flex;height:6px;border-radius:99px;overflow:hidden;background:var(--line2)}
.tbar i{display:block;height:100%}
.tbar i.u,.ybar em.u{background-image:repeating-linear-gradient(45deg,var(--c3) 0 3px,var(--c1) 3px 6px)!important}
.tb-w .lab{font:500 9.5px var(--num);color:var(--ink3);margin-top:3px;text-align:right}
/* 범례 */
.lgd{display:flex;align-items:center;gap:13px;flex-wrap:wrap;font-size:12px;color:var(--ink2)}
.lgd .li{display:flex;align-items:center;gap:5px;white-space:nowrap}
.lgd em{width:9px;height:9px;border-radius:3px;display:block}
.lgd em.u{background-image:repeating-linear-gradient(45deg,var(--c3) 0 3px,var(--c1) 3px 6px)}
.lgd .sub{color:var(--ink3)}
.gbar{display:none}
.gbar i{height:100%}

/* ── 논문 목록 ── */
.plist{padding:2px 15px 12px 60px;background:var(--c0);border-bottom:1px solid var(--line2)}
.jg{margin-top:8px;border:1px solid var(--line);border-radius:11px;overflow:hidden;background:var(--c0)}
.jh{display:flex;align-items:center;gap:8px;padding:7px 11px;background:var(--c1);border-bottom:1px solid var(--line2);font-size:13px}
.jh b{font-weight:700;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.jh .jm{font:500 12px var(--num);color:var(--ink3);flex-shrink:0;font-variant-numeric:tabular-nums}
.pr{display:flex;align-items:center;gap:9px;padding:6px 11px;border-bottom:1px solid var(--c1);font-size:13px}
.pr:last-child{border-bottom:0}
.pr .yy{font:600 12px var(--num);color:var(--ink3);width:34px;flex-shrink:0;font-variant-numeric:tabular-nums}
.pr .tt{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--s-blue)}
.tag{font-size:9.5px;font-weight:700;padding:1px 6px;border-radius:5px;flex-shrink:0}
.g-SCI{background:var(--t-blue);color:var(--s-blue)} .g-KCI{background:var(--t-lime);color:var(--s-amber)} .g-기타{background:var(--c1);color:var(--s-blue)}
.r-main{background:var(--t-red);color:var(--s-red)} .r-co{background:var(--c1);color:var(--s-blue)}
.t-if{background:var(--c2);color:var(--s-green)} .t-c{background:var(--t-lime);color:var(--s-amber)}
.t-pc{background:var(--c1);color:var(--s-blue)} .t-dp{background:var(--t-red);color:var(--s-red)} .t-af{background:var(--t-blue);color:var(--s-blue)} .t-sh{background:var(--c1);color:var(--s-red)} .t-bf{background:var(--t-amber);color:var(--s-amber)}
.empty{padding:26px;text-align:center;color:var(--ink3);font-size:13px}
.note{font-size:12px;color:var(--ink3);padding:9px 15px;background:var(--c0);border-bottom:1px solid var(--line2)}
.note b{color:var(--ink2)}
/* ── 연구자 상세 패널 ── */
.scrim{position:fixed;inset:0;background:rgba(20,26,41,.28);opacity:0;pointer-events:none;transition:.18s;z-index:60}
.scrim.on{opacity:1;pointer-events:auto}
.drw{position:fixed;top:0;right:0;bottom:0;width:430px;max-width:92vw;background:var(--card);z-index:61;
 box-shadow:-16px 0 44px rgba(20,30,60,.16);transform:translateX(100%);transition:transform .22s cubic-bezier(.4,0,.2,1);
 display:flex;flex-direction:column}
.drw.on{transform:none}
@media(prefers-reduced-motion:reduce){.drw{transition:none}}
.drw .dh{padding:20px 22px 14px;border-bottom:1px solid var(--line2);flex-shrink:0;position:relative}
.drw .dh h2{margin:0;font-size:21px;font-weight:800;letter-spacing:-.7px;padding-right:40px}
.drw .dh .sub{font-size:13px;color:var(--ink2);margin-top:5px;line-height:1.5}
.drw .dh .sub em{font-style:normal;color:var(--ink3)}
.drw .x{position:absolute;top:18px;right:18px;width:32px;height:32px;border-radius:10px;background:var(--muted);
 display:grid;place-items:center;color:var(--ink2);font-size:15px;transition:.14s}
.drw .x:hover{background:var(--c2);color:var(--ink)}
.drw .db{overflow:auto;flex:1;min-height:0;padding:16px 22px 28px}
.drw .alert{background:var(--c1);border:1px solid var(--s-lime);border-radius:12px;padding:11px 13px;margin-bottom:14px}
.drw .alert b{display:block;font-size:13px;color:var(--s-amber);font-weight:700}
.drw .alert i{font-style:normal;font-size:12px;color:var(--s-lime)}
.dgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px}
.dbox{background:var(--muted);border-radius:12px;padding:11px 13px}
.dbox .l{font-size:12px;color:var(--ink3);font-weight:600}
.dbox .n{font:600 21px var(--num);letter-spacing:-.8px;margin-top:3px;font-variant-numeric:tabular-nums}
.dsec{margin-bottom:18px}
.dsec h4{margin:0 0 9px;font-size:12px;font-weight:700;color:var(--ink3);letter-spacing:.2px}
.jl{display:flex;align-items:center;gap:9px;padding:5px 0;font-size:12px}
.jl .t{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink)}
.jl .b{width:96px;height:6px;border-radius:99px;background:var(--line2);overflow:hidden;flex:none}
.jl .b i{display:block;height:100%;background:var(--s-blue);border-radius:99px}
.jl .c{width:28px;text-align:right;font:600 12px var(--num);font-variant-numeric:tabular-nums}
.tp{padding:9px 0;border-bottom:1px solid var(--line2)}
.tp:last-child{border-bottom:0}
.tp a,.tp span.nt{font-size:13px;font-weight:600;color:var(--ink);line-height:1.45;display:block;text-decoration:none}
.tp a:hover{color:var(--accent);text-decoration:underline}
.tp .m{font-size:12px;color:var(--ink3);margin-top:3px}
.tp .m b{color:var(--ink2)}
/* 논문 제목 링크 */
.pr .tt a{color:inherit;text-decoration:none}
.pr .tt a:hover{color:var(--accent);text-decoration:underline}
.nmw .n1 .pn{cursor:pointer;border-radius:5px;padding:0 2px;margin:0 -2px}
.nmw .n1 .pn:hover{background:var(--t-blue);color:var(--s-blue)}
@media(max-width:1400px){.stat{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:1200px){.kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.split{grid-template-columns:280px 1fr}.stat{grid-template-columns:1fr}}

/* ══════════ 모바일 ══════════ */
@media(max-width:900px){
 .app{min-height:0}
 /* 좌측 레일을 화면 아래 탭바로 내린다 */
 .rail{position:fixed;left:0;right:0;bottom:0;top:auto;width:100%;flex:none;height:auto;z-index:120;
  flex-direction:row;align-items:stretch;gap:2px;padding:6px 6px calc(6px + env(safe-area-inset-bottom));
  overflow-x:auto;overflow-y:hidden;background:var(--c0);border-top:1px solid var(--line);
  box-shadow:0 -6px 20px rgba(7,23,57,.14);scrollbar-width:none}
 .rail::-webkit-scrollbar{display:none}
 .rail .logo{display:none}
 .rail .sp{display:none}
 .rail button{width:auto;flex:0 0 auto;min-width:62px;padding:7px 9px 6px;border-radius:11px}
 .rail button span{font-size:10.5px;line-height:1.2}
 .rail button i{font-size:16px}
 .rail button.hero::after,.rail button.hero2::after{display:none}
 .main{padding:12px 12px 92px;gap:11px}
 .top{gap:9px;position:static}
 .top h1{font-size:18px;letter-spacing:-.5px}
 .top .sub{font-size:12px}
 .search{max-width:none;flex:1 1 100%;order:9;padding:8px 13px}
 /* 여러 칸 배치는 한 줄로 */
 .kpis,.dkpis,.stat,.road{grid-template-columns:repeat(2,minmax(0,1fr)) !important;gap:8px}
 .split,.erow,.e2,.erow.n2,.trk{grid-template-columns:minmax(0,1fr) !important}
 .split{display:flex;flex-direction:column}
 .pane{padding:10px;border-radius:16px}
 .scroll{max-height:none}
 .ecard{padding:13px 12px;border-radius:16px}
 .ecard h3{font-size:15px}
 /* 표는 칸을 줄이지 말고 옆으로 밀어 본다 — 감싸개가 없는 표도 카드 안에서 스크롤되게 */
 .ecard,.xpanel,.pane{overflow-x:auto}
 .mtx{min-width:720px}
 .rkx{min-width:860px}
 .modal{padding:10px}
 .modal .mbox{max-height:88vh;padding:18px 16px}
 .modal .dev .dl .n{flex:0 0 120px;font-size:12px}
 .modal .dev .dl .v{flex:0 0 74px}
 .modal .mrow{flex-direction:column;gap:3px}
 .modal .mrow b{flex:none}
 .xmets{gap:8px}
 .xrow{flex-wrap:wrap}
 .xstart .t{font-size:15px}
 .netsvg{height:420px}
 /* 트리 행의 지표 묶음이 화면을 밀어내지 않게 */
 .mx{flex-wrap:wrap;row-gap:4px;min-width:0}
 .row,.row .nm,.dtl,.pane>*{min-width:0}
 .tree,.dtl{overflow-x:auto}
}
@media(max-width:560px){
 .kpis,.dkpis,.stat,.road{grid-template-columns:minmax(0,1fr) !important}
 .top h1{font-size:16.5px}
 .main{padding:10px 9px 92px}
 .rail button{min-width:56px}
 .rail button span{font-size:10px}
 .xmets{display:none}
}
.dt .udot{width:8px;height:8px;border-radius:3px;display:inline-block;margin-right:6px;vertical-align:0}

/* ── 연구자 카드 ── */
.prn{font:inherit;color:inherit;text-align:left;padding:0;border-bottom:1px dashed var(--c3);cursor:pointer}
.prn:hover{color:var(--accent);border-bottom-color:var(--accent)}
.prbox{max-width:660px}
.prhead{display:flex;align-items:center;gap:11px;margin:0 0 13px}
.prhead .av,.prhead .xav{width:40px;height:40px;border-radius:12px;font-size:15px}
.prhead h4{margin:0;font-size:18px;font-weight:800;display:flex;align-items:center;gap:7px}
.prhead .sub{font-size:12px;color:var(--ink3);margin-top:2px}
.prmail{display:flex;align-items:center;gap:9px;flex-wrap:wrap;background:var(--info-bg);
 border:1px solid var(--info-bd);border-left:3px solid var(--info-ac);border-radius:11px;padding:11px 13px}
.prmail .lb{font-size:11px;font-weight:800;color:var(--ink3);letter-spacing:.02em}
.prmail .ml{font:600 14px var(--num);color:var(--ink);word-break:break-all;flex:1;min-width:150px}
.prmail.none .ml{font-family:var(--ui);font-weight:600;color:var(--ink3)}
.prmail .hint{flex-basis:100%;font-size:11.5px;color:var(--ink3)}
.prmail .cp{font:700 12px var(--ui);padding:5px 12px;border-radius:8px;background:var(--sel-bg);color:var(--sel-fg);
 border:1px solid transparent;transition:.13s;text-decoration:none;display:inline-block}
.prmail .cp:hover{opacity:.86}
.prmail .cp.ok{background:var(--s-green);color:var(--on-solid)}
.prmail .cp.go{background:transparent;color:var(--ink2);border-color:var(--c3)}
.prsec{margin-top:15px}
.prsec .st{font-size:12px;font-weight:800;color:var(--ink);margin-bottom:7px;display:flex;align-items:center;gap:6px}
.prsec .st em{font-style:normal;font-weight:600;color:var(--ink3);font-size:11.5px}
.prkv{font-size:13px;color:var(--ink2);display:flex;align-items:center;gap:7px}
.prkv b{color:var(--ink);font-weight:700}
.prkv.sm{font-size:12px;color:var(--ink3);margin-top:3px}
.prkv.warn b{color:var(--s-red)}
.prlinks{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}
.prlink{font:700 11.5px var(--ui);padding:4px 10px;border-radius:8px;background:var(--t-blue);color:var(--s-blue);text-decoration:none}
.prlink:hover{filter:brightness(.96)}
.prlink.off{background:var(--c1);color:var(--ink3)}
.prm{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.prm>div{background:var(--c1);border-radius:10px;padding:8px 10px;text-align:center}
.prm b{display:block;font:700 15px var(--num);color:var(--ink);font-variant-numeric:tabular-nums}
.prm span{font-size:11px;color:var(--ink3)}
.prm.oa{margin-top:7px}
.prm.oa>div{background:var(--t-blue)}
.prm.oa b{color:var(--s-blue)}
.prnote{font-size:11.5px;color:var(--ink3);margin-top:6px}
.prw{display:grid;grid-template-columns:1fr auto;gap:2px 12px;padding:9px 11px;border-radius:10px;
 border:1px solid var(--line);margin-bottom:6px;text-decoration:none;color:inherit;transition:.13s}
a.prw:hover{border-color:var(--accent);background:var(--info-bg)}
.prw .tt{font-size:13px;font-weight:700;color:var(--ink);line-height:1.4;grid-column:1;grid-row:1}
.prw .mt{font-size:11.5px;color:var(--ink3);grid-column:1;grid-row:2}
.prw .mt code{font-family:var(--num);font-size:11px}
.prw .cc{grid-column:2;grid-row:1/3;align-self:center;min-width:52px;text-align:right;font:700 14px var(--num);color:var(--s-blue);font-variant-numeric:tabular-nums}
.prw .cc em{display:block;font-style:normal;font-size:10.5px;font-weight:600;color:var(--ink3)}
.prw.nodoi{opacity:.72}
.prfoot{margin-top:14px;padding-top:11px;border-top:1px solid var(--line2);font-size:11.5px;color:var(--ink3);line-height:1.55}
@media(max-width:900px){ .prm{grid-template-columns:repeat(2,minmax(0,1fr))} .prbox{max-width:none} }

/* ── 데이터 풀 구조도 ── */
.poolhd h2 span{color:var(--pl-ac)}
/* 시각화 무대는 밝은 화면에서도 어두운 배경으로 고정한다 — 유리 큐브는 어두운 바탕에서만 보인다 */
.ecard.poolc{padding:6px 8px;border-color:rgba(96,165,250,.20);
 background:radial-gradient(1200px 800px at 50% 34%, #0d1730 0%, #070d1c 55%, #04070f 100%)}
.ecard.poolc{--pl-ac:#7dd3fc; --pl-hot:#cfe8ff; --pl-edge:#4a6fa5; --pl-edge2:rgba(96,165,250,.22);
 --pl-top:#7fb2ff; --pl-lf:#1e3a6e; --pl-rt:#0d1c38; --pl-plate:#0a1730; --pl-dot:#7dd3fc;
 --ink:#e8eefc; --ink2:#8fa3c8; --ink3:#5b6d92}
.poolwrap{width:100%;overflow-x:auto}
.pscene{display:block;width:100%;min-width:900px;height:auto;overflow:visible}
.pscene .pface{stroke:var(--pl-edge);stroke-width:.9;stroke-opacity:.62;fill:none}
.pscene .pf-top{fill:var(--pl-top);fill-opacity:.06}
.pscene .pf-l{fill:var(--pl-lf);fill-opacity:.18}
.pscene .pf-r{fill:var(--pl-rt);fill-opacity:.30}
.pscene .pplate{fill:var(--pl-plate);fill-opacity:.6;stroke:var(--pl-edge);stroke-width:.8;stroke-opacity:.5}
.pscene .pnode{cursor:pointer}
.pscene .pnode:hover .pf-top,.pscene .pnode:focus-visible .pf-top{fill-opacity:.14}
.pscene .pnode:hover .pface,.pscene .pnode:focus-visible .pface{stroke:var(--pl-ac);stroke-opacity:1}
.pscene .pnode.on .pface{stroke:var(--pl-ac);stroke-opacity:1}
.pscene .pnode.on .pf-top{fill-opacity:.16}
.pscene .pnode:focus{outline:none}
.pscene .plink{stroke:var(--pl-ac);stroke-width:1.3;stroke-opacity:.34;fill:none}
.pscene .plink.on{stroke:var(--pl-ac);stroke-opacity:.95;stroke-width:2.1}
.pscene .ppulse{stroke:var(--pl-ac);stroke-width:2.4;fill:none;stroke-linecap:round;
 filter:url(#pglow);stroke-dasharray:16 300}
.pscene .pnum{font:700 12px/1 var(--num);fill:var(--ink3);letter-spacing:.14em}
.pscene .pttl{font:800 15px/1 var(--ui);fill:var(--ink);letter-spacing:-.3px}
.pscene .pcnt{font:700 13px/1 var(--num);fill:var(--pl-ac);letter-spacing:.02em}
.pscene .pdsc{font:400 11.5px/1.5 var(--ui);fill:var(--ink3)}
.pscene .phub-t{font:800 17px/1 var(--ui);fill:var(--ink);letter-spacing:-.4px}
.pscene .phub-s{font:600 11px/1 var(--num);fill:var(--ink3);letter-spacing:.16em}
.ppanel{min-height:150px}
.ppn{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:13px}
.ppn .ix{font:700 11px/1 var(--num);color:var(--ink3);letter-spacing:.2em}
.ppn h3{margin:0;font-size:18px;font-weight:800;letter-spacing:-.5px}
.ppn .ptag{font:700 10.5px/1 var(--num);padding:5px 11px;border-radius:999px;
 border:1px solid var(--pl-edge2);color:var(--pl-ac);letter-spacing:.06em}
.ppgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:10px}
.ppit{border:1px solid var(--line);border-radius:13px;padding:11px 13px;background:var(--c1)}
.ppit.main{border-color:var(--pl-edge2);background:var(--pl-stage)}
.ppit .k{font-size:11px;color:var(--ink3);font-weight:600}
.ppit .v{font:800 20px/1.2 var(--num);color:var(--ink);margin-top:5px;letter-spacing:-.5px;font-variant-numeric:tabular-nums}
.ppit.main .v{color:var(--pl-ac)}
.ppit .s{font-size:10.5px;color:var(--ink3);margin-top:3px}
.ppd{color:var(--ink2);font-size:12.5px;line-height:1.8;margin-top:13px}
.ppd b{color:var(--ink)}
.ppd code,.play code{font:600 11px var(--num);background:var(--pl-stage);border:1px solid var(--pl-edge2);
 padding:1px 6px;border-radius:5px;color:var(--pl-ac)}
.players{margin-top:0}
