/* ── 경영자 KPI 보드 ── */
#v-tree{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0}
#v-exec{display:flex;flex-direction:column;gap:12px;min-height:0;flex:1;overflow:auto;padding-right:3px}
