/* 이 화면이 무엇을 보여 주는지 — 노란 정보 박스 */
.ehead .ex,.top .sub.info{flex-basis:100%;width:100%;font-size:13px;color:var(--ink2);line-height:1.6;
 background:var(--info-bg);border:1px solid var(--info-bd);border-left:3px solid var(--info-ac);
 border-radius:10px;padding:9px 13px;margin-top:3px;position:relative}
.ehead .ex b,.top .sub.info b{color:var(--ink)}
.ehead .ex code,.top .sub.info code{background:var(--veil62);border-radius:4px;padding:0 3px}
/* 이 화면이 무엇을 세었는지 — 초록 수치 배지 */
.ehead .n,.top .sub.num{font-size:12px;color:var(--num-fg);font-weight:600;
 background:var(--num-bg);border:1px solid var(--num-bd);border-radius:999px;padding:3px 11px}
.pill{font-size:12px;font-weight:700;padding:2px 9px;border-radius:999px;background:var(--muted);color:var(--ink2)}
.pill.off{background:var(--t-blue);color:var(--s-blue)} .pill.px{background:var(--t-violet);color:var(--s-violet)} .pill.in{background:var(--c1);color:var(--s-blue)}
.pill.prov{background:var(--t-lime);color:var(--s-amber)}
/* 등급 배지 [6] — 숫자 옆에 판정 근거(why)를 같이 적는다. */
.gtag{display:inline-block;min-width:20px;text-align:center;font:700 12px/1.5 var(--num);
 border-radius:6px;padding:1px 5px;background:var(--g0t);color:var(--g0s)}
.gtag.g6{background:var(--g6t);color:var(--g6s)} .gtag.g5{background:var(--g5t);color:var(--g5s)}
.gtag.g4{background:var(--g4t);color:var(--g4s)} .gtag.g3{background:var(--g3t);color:var(--g3s)}
.gtag.g2{background:var(--g2t);color:var(--g2s)} .gtag.g1{background:var(--g1t);color:var(--g1s)}
/* 등급 구성 누적 막대. 편수 0 인 칸은 렌더하지 않는다(0폭 칸이 테두리로 보인다). */
.gband{display:flex;height:9px;border-radius:5px;overflow:hidden;background:var(--c1);margin:2px 0 7px}
.gband i{display:block;height:100%}
.gband i.g6{background:var(--g6s)} .gband i.g5{background:var(--g5s)}
.gband i.g4{background:var(--g4s)} .gband i.g3{background:var(--g3s)}
.gband i.g2{background:var(--g2s)} .gband i.g1{background:var(--g1s)}
.gband i.g0{background:var(--c3)}
.gkey{display:flex;flex-wrap:wrap;gap:4px 10px;font-size:11px;color:var(--ink3);
 font-variant-numeric:tabular-nums}
