/* 논문별 산출 내역 표 — .mtx 변형. 한 논문이 2행(제목/게재지)을 쓴다. */
.pbreak{min-width:0;font-size:12px}
.pbreak td{padding:7px 6px;border-bottom:1px solid var(--line2);vertical-align:top;text-align:center}
