.misr .b i{display:block;height:100%;background:var(--s-amber)}
.misr .v{text-align:right;font-variant-numeric:tabular-nums;font-weight:700;color:var(--ink)}
.misr .v em{font-style:normal;font-weight:500;color:var(--ink3);margin-left:5px;font-size:11px}
