/* ══ 개인성과 대시보드 (biblo.ai/2026/#16 이식) ══
   원본 CSS 를 .rpwrap 아래로 스코프해 넣는다. .rpbar·.card·.rptag 처럼 흔한 이름이
   보드와 겹치므로 스코프가 없으면 서로 덮어쓴다. */
/* 원본은 1718×812 고정 무대에 절대좌표로 놓는다. 격자로 바꾸면 여백·글자가 다 틀어진다.
   원본이 하는 대로 «폭에 맞춰 통째로 배율» 을 준다. 그래야 슬라이드와 똑같이 보인다. */
.rpwrap{position:relative;margin-top:12px;color:#e8eeff;overflow:hidden;
 border-radius:18px;background:#0b1020}
.rpwrap .rpboard{position:absolute;left:0;top:0;width:1718px;height:812px;
 transform-origin:top left}
.rpwrap .bgfx{pointer-events:none}
/* 검색 안내줄이 두 줄로 접히면 그만큼 메뉴가 잘린다. 한 줄로 고정한다. */
.rpwrap .menu .rpsearch{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
 display:block;line-height:1.5}
/* 안전장치 — 폰트·번역으로 높이가 달라져도 항목이 소리 없이 사라지지 않게 한다.
   원본은 overflow:hidden 이라 넘치면 그냥 잘렸다. */
.rpwrap .mlist{overflow-y:auto;scrollbar-width:thin}
.rpwrap .mlist::-webkit-scrollbar{width:5px}
.rpwrap .mlist::-webkit-scrollbar-thumb{background:rgba(147,166,204,.35);border-radius:3px}
/* 좁은 화면 — 배율을 더 줄이면 글자가 4px 이 된다. 축소가 아니라 «쌓기» 로 바꾼다.
   절대좌표 무대를 흐름 배치로 풀고 세 칸을 위에서 아래로 놓는다. */
.rpwrap.stack{height:auto !important}
.rpwrap.stack .rpboard{position:relative;width:100%;height:auto;transform:none !important;
 display:flex;flex-direction:column;gap:12px;padding:12px}
.rpwrap.stack .phone,.rpwrap.stack .menu,.rpwrap.stack .panel{
 position:relative !important;left:auto !important;top:auto !important;
 width:100% !important;height:auto !important;min-height:0}
.rpwrap.stack .phone{border-radius:20px;max-height:none}
.rpwrap.stack .mlist{overflow:visible;justify-content:flex-start;gap:2px}
.rpwrap.stack .panel{min-height:420px}
.rpwrap.stack .bgfx{height:100%}

