/* ── 데이터 근거 ── */
.srcc,.srcnet,.srcall{border-color:var(--info-bd);background:linear-gradient(180deg,var(--info-bg),var(--card) 120px)}
.srcc h3 .si,.srcnet h3 .si,.srcall h3 .si{font-style:normal;color:var(--info-ac);margin-right:2px}
