.srcrow{display:grid;grid-template-columns:1.4fr 1fr;gap:10px;margin-top:6px}
.srcrow>div{background:var(--c1);border-radius:10px;padding:9px 12px}
.srcrow .k{display:block;font-size:11px;font-weight:700;color:var(--ink3);margin-bottom:3px}
.srcrow b{font-size:12.5px;color:var(--ink);font-weight:700;line-height:1.55}
.srcdet{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin-top:11px}
