.srcdet ul,.srcdet ol{margin:0;padding-left:17px}
.srcdet li{font-size:12px;color:var(--ink2);line-height:1.7;margin-bottom:3px}
.srcdet li code{font:600 11px var(--num);background:var(--card);border:1px solid var(--line);
 padding:1px 6px;border-radius:5px;color:var(--s-blue)}
