.srcdet p{margin:0;font-size:12px;color:var(--ink2);line-height:1.75}
.srcdet p b{color:var(--ink)}
/* 관계망 만드는 법 */
.nsteps{display:flex;flex-direction:column;gap:7px;margin-top:10px}
.ns{display:grid;grid-template-columns:30px 1fr auto;gap:11px;align-items:start;
 background:var(--c1);border-radius:12px;padding:11px 13px;border-left:3px solid var(--s-blue)}
.ns .no{display:grid;place-content:center;width:26px;height:26px;border-radius:8px;
 background:var(--s-blue);color:var(--on-solid);font:800 12px var(--num)}
