.nfact b{display:block;font:800 17px var(--num);color:var(--ink);margin:2px 0 3px;font-variant-numeric:tabular-nums}
.nfact .s{font-size:11px;color:var(--ink3)}
.d.warn2{margin-top:11px;background:var(--t-amber);border-radius:11px;padding:11px 13px;
 font-size:12px;color:var(--ink2);line-height:1.75}
.d.warn2 b{color:var(--s-amber)}
/* 네 갈래 전체 */
.slayers{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin-top:8px}
.sl{border:1px solid var(--line);border-left:3px solid var(--sc);border-radius:13px;padding:12px 14px;background:var(--card)}
.sl .lt{font-size:14px;font-weight:800;color:var(--sc)}
