@media(max-width:900px){ .srcrow,.srcdet,.nfact,.slayers{grid-template-columns:minmax(0,1fr)}
 .ns{grid-template-columns:26px 1fr}.ns .nv{grid-column:2}}

.sterm{margin-top:12px;border:1px solid var(--line);border-left:3px solid var(--info-ac);border-radius:13px;padding:13px 15px;background:var(--info-bg)}
