@media(max-width:900px){ .sterm .tg{grid-template-columns:minmax(0,1fr)} .sterm .tg>div{grid-template-columns:92px 1fr} }


/* 국제 ↔ 국내 순위 (막대 + 숫자 + 연결선) */
