.dl{display:flex;align-items:center;gap:9px;padding:5px 0;font-size:12px}
.dl .n{width:150px;flex:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
.dl .n:hover{color:var(--accent)}
