.dl .bar{flex:1;height:9px;background:var(--line2);border-radius:99px;overflow:hidden;position:relative}
.dl .bar.avg::after{content:'';position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--s-blue)}
