.fl{display:flex;gap:6px;flex-wrap:wrap}
.fbtn{padding:4px 11px;border:1px solid var(--line);background:var(--c0);border-radius:999px;font-size:12px;font-weight:600;color:var(--ink2);transition:.12s}
.fbtn:hover{border-color:var(--s-blue)}
.fbtn.on{background:var(--navy);color:var(--on-solid);border-color:var(--navy)}
.mtx td.num{text-align:right;font:600 12px var(--num);font-variant-numeric:tabular-nums}
.pcell{display:inline-flex;align-items:center;gap:5px;justify-content:flex-end;min-width:58px}
.pcell .pb{width:26px;height:5px;border-radius:99px;background:var(--line2);overflow:hidden;flex:none}
.pcell .pb i{display:block;height:100%;border-radius:99px}
.gys{font-size:9.5px;font-weight:700;padding:2px 7px;border-radius:999px;color:var(--on-solid)}
.qb{font-size:11px;font-weight:600;padding:2px 7px;border-radius:6px;background:var(--c1);color:var(--ink3);white-space:nowrap}
.qb.bad{background:var(--t-lime);color:var(--s-amber)}
