.tk.a{border-left-color:var(--s-blue);background:var(--c1)} .tk.a b{color:var(--s-blue)}
.tk.b{border-left-color:var(--s-green);background:var(--c1)} .tk.b b{color:var(--s-green)}
.tk.w{border-left-color:var(--s-blue)}
