.ac{display:inline-block;font-size:12px;font-weight:700;padding:3px 9px;border-radius:7px;white-space:nowrap}
.ac-q{background:var(--c1);color:var(--s-blue)} .ac-p{background:var(--t-red);color:var(--s-red)}
.ac-w{background:var(--t-lime);color:var(--s-amber)} .ac-k{background:var(--c1);color:var(--s-green)}
