.dev .sub-t{margin:15px 0 4px}
/* 성균관대 워드마크 */
.rail .logo span{font:800 12px/1 var(--ui);letter-spacing:.04em;text-align:center}
.rail .logo em{font:600 7.5px/1 var(--ui);font-style:normal;opacity:.82;letter-spacing:.02em;text-align:center}
/* 관계망 */
#v-net{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0;overflow:auto;padding-right:2px}
.erow.n2{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:14px}
