.netx tr.sel td{background:var(--t-blue);box-shadow:inset 0 0 0 1px var(--t-blue)}
/* 다음 단계 로드맵 */
.road{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.rd{border:1px solid var(--line);border-radius:13px;padding:12px 13px;background:var(--c0);position:relative}
.rd b{display:inline-grid;place-content:center;width:21px;height:21px;border-radius:7px;background:var(--c1);color:var(--ink3);font:800 12px var(--num);margin-bottom:7px}
.rd h6{margin:0 0 4px;font-size:13px;font-weight:800;color:var(--ink)}
.rd p{margin:0;font-size:12px;color:var(--ink2);line-height:1.55}
.rd.ready{background:var(--c1);border-color:var(--s-green)} .rd.ready b{background:var(--t-green);color:var(--s-green)}
.rd.plan{background:var(--c0);border-style:dashed}
