/* 분야 검색 · 추천 */
.srch{display:flex;flex-direction:column;gap:9px;margin:4px 0 13px}
.srch input{width:100%;padding:11px 15px;border:1px solid var(--line);border-radius:12px;background:var(--c0);
 font:600 13.5px var(--ui);color:var(--ink);transition:.12s}
.srch input::placeholder{color:var(--s-blue);font-weight:500}
.srch input:focus{outline:none;border-color:var(--navy);background:var(--c0);box-shadow:0 0 0 3px rgba(46,58,89,.09)}
.rsel{padding:4px 10px;border:1px solid var(--line);border-radius:999px;background:var(--c0);font:600 12px var(--ui);color:var(--ink2);max-width:210px}
.fbtn.off{opacity:.42;cursor:not-allowed}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:13px}
.chip{padding:4px 10px;border:1px solid var(--line);background:var(--c0);border-radius:999px;font:600 12px var(--ui);color:var(--ink2);transition:.12s}
.chip:hover{border-color:var(--s-blue);background:var(--c1)}
.chip em{font-style:normal;font:600 11px var(--num);color:var(--ink3);margin-left:5px}
.chip.on{background:var(--navy);color:var(--on-solid);border-color:var(--navy)} .chip.on em{color:var(--t-blue)}
