.rtab .aff{font-size:12px;color:var(--ink2);display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rtab .dn{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* 협업 매트릭스 */
.nmw{overflow:auto;max-width:100%;padding-bottom:4px}
.nmx{border-collapse:separate;border-spacing:2px;font-size:11px}
.nmx th{font-weight:600;color:var(--ink2);background:transparent;position:static}
.nmx th.rh{text-align:right;padding-right:8px;white-space:nowrap;cursor:pointer;font-size:12px;max-width:132px;overflow:hidden;text-overflow:ellipsis}
.nmx th.rh:hover{color:var(--accent)}
.nmx th.ch{height:86px;vertical-align:bottom;padding:0}
.nmx th.ch div{writing-mode:vertical-rl;transform:rotate(180deg);white-space:nowrap;margin:0 auto;color:var(--ink3);font-size:9.5px}
.nmx td{width:17px;height:17px;border-radius:3px;cursor:pointer;transition:.1s}
.nmx td:hover{outline:2px solid var(--navy);outline-offset:1px}
.nmx td.dg{box-shadow:inset 0 0 0 1.5px var(--s-blue)}
.nmx tr.on th.rh{color:var(--navy);font-weight:800}
.nmx tr.on td{outline:1px solid var(--t-blue)}
.nmlg{display:flex;align-items:center;gap:6px;margin-top:10px;font-size:12px;color:var(--ink3);flex-wrap:wrap}
.nmlg i{width:15px;height:11px;border-radius:3px;display:inline-block}
/* 협업 상세 */
.rel{border:1px solid var(--line2);border-radius:10px;padding:8px 11px;margin-bottom:6px;background:var(--c0)}
.rel .p{display:flex;align-items:center;gap:5px;flex-wrap:wrap;font-size:13px}
.rel .p b{font-weight:800;color:var(--ink)}
.rel .ar{color:var(--ink3);margin:0 1px}
.rel .jk{font-size:9.5px;font-weight:700;padding:1.5px 6px;border-radius:999px;background:var(--t-blue);color:var(--s-blue)}
.rel .jk.st{background:var(--t-violet);color:var(--s-violet)}
.rel .od{font-size:11px;font-weight:700;color:var(--ink3);background:var(--c1);padding:2px 7px;border-radius:6px;cursor:pointer;margin-left:auto}
.rel .od:hover{color:var(--accent)}
.rel .m{margin-top:4px;font-size:12px;color:var(--ink3);font-variant-numeric:tabular-nums}
/* 글로벌 관계망 */
#v-glob{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0;overflow:auto;padding-right:2px}
.tmap{display:flex;gap:5px;height:82px;margin:2px 0 4px}
.tm{border-radius:10px;padding:9px 11px;color:var(--on-solid);cursor:pointer;overflow:hidden;min-width:52px;
 display:flex;flex-direction:column;justify-content:flex-end;transition:.14s;opacity:.9}
.tm:hover{opacity:1;transform:translateY(-2px)}
.tm.on{outline:2.5px solid var(--ink);outline-offset:2px;opacity:1}
.tm b{font-size:13px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm span{font:600 11px var(--num);opacity:.86;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ybar2{display:flex;align-items:flex-end;gap:5px;height:150px;padding-top:16px}
.yb2{flex:1;background:var(--t-blue);border-radius:4px 4px 0 0;position:relative;min-height:3px;transition:.12s}
.yb2.on{background:var(--navy)}
.yb2:hover{filter:brightness(1.15)}
.yb2 em{position:absolute;top:-15px;left:50%;transform:translateX(-50%);font:600 9px var(--num);color:var(--ink3);font-style:normal;white-space:nowrap}
.yb2 span{position:absolute;bottom:-16px;left:50%;transform:translateX(-50%);font:600 9.5px var(--num);color:var(--ink3)}
.ybar2{margin-bottom:20px}
.globx tr[data-gd]{cursor:pointer}
.globx tr.sel td{background:var(--t-blue);box-shadow:inset 0 0 0 1px var(--t-blue)}
.globx .dn{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rtab .aff[data-gd]{cursor:pointer} .rtab .aff[data-gd]:hover{color:var(--accent)}
.ncol{display:flex;flex-direction:column;gap:14px;min-width:0}
.erow.n2{align-items:stretch}
#nsideC{display:flex;flex-direction:column;min-width:0}
#nside{flex:1;overflow:auto;min-height:0}
/* 분야 협력 탐색 */
#v-exp{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0;overflow:auto;padding-right:2px}
.flab{font-size:12px;color:var(--ink3);font-weight:600;margin:0 2px 0 6px;align-self:center}
.xhead{display:flex;align-items:center;gap:9px;flex-wrap:wrap;border-top:1px solid var(--line2);padding-top:12px}
.xhead b{font-size:15px;font-weight:800;color:var(--ink)}
.xclick{cursor:pointer;transition:.12s}
.xclick:hover{color:var(--accent)}
.xclick::after{content:" ↩";font-size:13px;font-weight:600;color:var(--ink3);opacity:0;transition:.12s}
.xclick:hover::after{opacity:1}
.xhead .xcode{font-size:12px;color:var(--ink3);background:var(--c1);padding:2px 8px;border-radius:6px}
.xhead span:not(.xcode){font-size:12px;color:var(--ink3);font-weight:600}
.xhint{margin-top:8px;font-size:12px;color:var(--ink2);background:var(--c1);border:1px solid var(--t-blue);border-radius:9px;padding:8px 11px}
.xpanel{border:1px solid var(--line);border-radius:14px;padding:13px 15px;background:var(--card);min-width:0}
.xph{display:flex;align-items:baseline;gap:9px;margin-bottom:9px;flex-wrap:wrap}
.xph h4{margin:0;font-size:13px;font-weight:800;color:var(--ink)}
.xph span{font-size:12px;color:var(--ink3);font-weight:600}
.xlst{max-height:640px;overflow:auto;padding-right:3px}
.xrow{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid var(--line2)}
.xrow:last-child{border-bottom:none}
.xrk{width:19px;flex:none;text-align:right;font:700 12px var(--num);color:var(--s-blue)}
.xav{width:29px;height:29px;flex:none;border-radius:9px;display:grid;place-items:center;font:700 12px var(--ui)}
.xwho{flex:1;min-width:0}
.xwho .n{font-size:13px;font-weight:700;color:var(--ink);display:flex;align-items:center;gap:4px;flex-wrap:wrap}
.xwho .m{font-size:12px;color:var(--ink3);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.xb{font-size:9px;font-weight:700;padding:1.5px 6px;border-radius:999px;white-space:nowrap}
.xb.nw{background:var(--t-red);color:var(--s-red)} .xb.od{background:var(--c1);color:var(--s-blue)}
.xb.il{background:var(--t-blue);color:var(--s-blue)} .xb.kr{background:var(--t-green);color:var(--s-green)}
.xb.id{background:var(--t-violet);color:var(--s-violet)}
.xmets{display:flex;gap:11px;flex:none}
.xmets>div{text-align:right;min-width:38px}
.xmets b{display:block;font:700 13px var(--num);color:var(--ink);font-variant-numeric:tabular-nums}
.xmets span{font-size:9px;color:var(--ink3)}
.xfoot{margin-top:13px;padding-top:11px;border-top:1px solid var(--line2);font-size:12px;color:var(--ink2);line-height:1.65}
.xfoot b{color:var(--ink)}
@media(max-width:1240px){.xmets{display:none}}
/* 분야 선택 — 갈래 필터 + 정렬 + 줄 목록 */
.xbar{display:flex;gap:14px;align-items:flex-start;flex-wrap:wrap;margin:2px 0 12px}
.xgs{display:flex;gap:6px;flex-wrap:wrap;flex:1;min-width:0}
.xg{display:inline-flex;align-items:center;gap:6px;padding:5px 11px;border:1px solid var(--line);background:var(--c0);
 border-radius:999px;font:600 12px var(--ui);color:var(--ink2);transition:.12s;white-space:nowrap}
.xg i{width:8px;height:8px;border-radius:3px;background:var(--gc,var(--s-blue));flex:none}
.xg em{font-style:normal;font:600 11px var(--num);color:var(--ink3)}
.xg:hover{border-color:var(--s-blue);background:var(--c1)}
.xg.on{background:var(--navy);color:var(--on-solid);border-color:var(--navy)} .xg.on em{color:var(--t-blue)} .xg.on i{background:var(--c0)}
.xsort{display:flex;gap:5px;align-items:center;flex:none}
.xsort span{font-size:12px;color:var(--ink3);font-weight:600;margin-right:2px}
.flist{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:13px;overflow:hidden;background:var(--card)}
.frow{display:grid;grid-template-columns:34px minmax(0,1.5fr) 96px minmax(90px,1fr) 62px 56px 62px 18px;
 align-items:center;gap:11px;padding:9px 13px;border:none;border-bottom:1px solid var(--line2);
 background:var(--c0);text-align:left;cursor:pointer;transition:.1s;width:100%;position:relative}
.frow:last-child{border-bottom:none}
.frow::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--gc);opacity:0;transition:.1s}
.frow:hover{background:var(--c1)} .frow:hover::before{opacity:1}
.frow .rk{font:600 12px var(--num);color:var(--s-blue);text-align:right}
.frow .nm{min-width:0;display:flex;flex-direction:column;gap:1px}
.frow .nm b{font-size:13px;font-weight:800;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.frow .nm em{font-style:normal;font-size:11px;color:var(--ink3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.frow .nm em u{text-decoration:none;color:var(--accent);font-weight:700}
.frow .gtag{font-size:9.5px;font-weight:700;color:var(--on-solid);padding:2.5px 8px;border-radius:999px;text-align:center;white-space:nowrap;
 overflow:hidden;text-overflow:ellipsis;opacity:.9}
.frow .bar{height:7px;background:var(--line2);border-radius:99px;overflow:hidden}
.frow .bar i{display:block;height:100%;border-radius:99px}
.frow .mt{text-align:right}
.frow .mt b{display:block;font:700 13px var(--num);color:var(--ink);font-variant-numeric:tabular-nums}
.frow .mt em{font-style:normal;font-size:9px;color:var(--ink3)}
.frow .go{font-size:15px;color:var(--s-blue);text-align:center}
.frow:hover .go{color:var(--navy)}
@media(max-width:1320px){.frow{grid-template-columns:30px minmax(0,1.4fr) 84px 56px 52px 56px 16px}.frow .bar{display:none}}
/* 세로 레이아웃 — 칸마다 따로 스크롤하지 않고 내용을 다 펼친다. 기본 높이 1800px. */
html,body{height:auto}
.app{height:auto;min-height:1800px;overflow:visible}
.rail{position:sticky;top:0;align-self:flex-start;height:100vh;overflow-y:auto;z-index:20}
.main{height:auto;min-height:0}
.top{position:sticky;top:0;z-index:15;background:linear-gradient(180deg,var(--bg) 72%,transparent);
 padding:10px 0 8px;margin:-10px 0 -4px}
#v-tree{flex:none;min-height:0}
.split{flex:none;min-height:0;align-items:start}
.pane{min-height:0}
.scroll{flex:none;max-height:1180px}
.tree{flex:none;overflow:visible}
.tb{flex:none;overflow:visible;max-height:none}
#v-exec,#v-net,#v-glob,#v-exp,#v-univ,#v-sheet,#v-pool{flex:none;overflow:visible;min-height:0}
/* 데이터풀만 카드가 붙어 있었다 — 다른 화면과 같은 세로 간격을 준다 */
#v-pool{display:flex;flex-direction:column;gap:14px}
.xlst{max-height:none;overflow:visible}
#nside{overflow:visible}
@media (max-height:900px){ .scroll{max-height:64vh} .netsvg{height:520px} }
@media (max-height:700px){ .scroll{max-height:58vh} .netsvg{height:460px} .top h1{font-size:19px} }
/* 대학 연구력 비교 */
#v-univ{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0}
.uvsvg{width:100%;height:360px;display:block}
.uvsvg.wide{height:300px}
.uvsvg text{font:500 9.5px var(--ui);fill:var(--ink3)}
.uvsvg text.ul{font:700 12px var(--ui);fill:var(--ink2)}
.uvsvg text.ul.me{font-size:12px;fill:var(--accent)}
.uvsvg circle{transition:.12s}
.udot{width:9px;height:9px;border-radius:3px;display:inline-block;margin-right:7px;vertical-align:middle}
.uvx tr[data-uv]{cursor:pointer}
.uvx tr.me td{background:var(--c1)}
.uvx tr.me .dn{color:var(--accent);font-weight:800}
.uvx tr.sel td{background:var(--t-blue);box-shadow:inset 0 0 0 1px var(--t-blue)}
.uvc td.dg{font-size:12px;color:var(--ink3)}
.uvsplit{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}
.uvs{border:1px solid var(--line);border-radius:13px;padding:13px 15px;background:var(--c0)}
.uvs.on{background:var(--c1);border-color:var(--t-amber)}
.uvs .k{font-size:13px;font-weight:800;color:var(--ink2)}
.uvs.on .k{color:var(--accent)}
.uvs .v{font:700 25px/1.1 var(--num);letter-spacing:-1px;margin-top:4px;color:var(--ink);font-variant-numeric:tabular-nums}
.uvs .v small{font:600 12px var(--ui);color:var(--ink3);margin-left:4px}
.uvs .m{display:flex;gap:12px;margin-top:6px;font-size:12px;color:var(--ink3);flex-wrap:wrap}
.uvs .m b{font:700 12px var(--num);color:var(--ink2)}
.uvs .m2{margin-top:5px;padding-top:6px;border-top:1px dashed var(--line);font-size:12px;color:var(--ink3)}
.uvs .m2 b{font:700 12px var(--num);color:var(--ink2)}
@media(max-width:1240px){.uvsplit{grid-template-columns:1fr}}
.ulg{display:inline-flex;align-items:center;gap:5px;cursor:pointer;padding:2px 7px;border-radius:999px;transition:.12s}
.ulg:hover{background:var(--t-blue)} .ulg.on{background:var(--navy);color:var(--on-solid)} .ulg.on i{box-shadow:0 0 0 2px var(--c0)}
.usort{cursor:pointer;user-select:none;transition:.12s}
.usort:hover{color:var(--ink)} .usort.on{color:var(--navy);font-weight:800}
.udual{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.udu .dl .n{font-size:12px;font-weight:700;color:var(--ink)}
.urk{display:inline-block;width:15px;font:700 11px var(--num);color:var(--s-blue);text-align:right;margin-right:6px}
.usrc{border:1px solid var(--line2);border-radius:10px;padding:9px 12px;margin-bottom:6px;background:var(--c0)}
.usrc b{font-size:13px;font-weight:800;color:var(--ink);margin-right:8px}
.usrc span{font-size:12px;color:var(--ink2)}
.usrc code{display:block;margin-top:4px;font:600 11px var(--num);color:var(--ink3);word-break:break-all}
@media(max-width:1240px){.udual{grid-template-columns:1fr}}
.ud{width:9px;height:9px;border-radius:3px;display:inline-block;margin:0 4px 0 8px;vertical-align:middle}
.ubn{margin-top:9px;padding:9px 12px;background:var(--c1);border-radius:9px;font-size:12px;color:var(--ink2);
 font-variant-numeric:tabular-nums}
.ubn b{color:var(--ink);font-weight:800}
.ubn span{color:var(--accent);font-weight:700}
/* 대학별 성과표 */
#v-sheet{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0}
.fbtn.meb{border-color:var(--accent);color:var(--accent)}
.fbtn.meb.on{background:var(--accent);border-color:var(--accent);color:var(--on-solid)}
.uc{background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:var(--sh);
 padding:18px 20px 20px;margin-bottom:14px}
.uc.me{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent),var(--sh)}
.uh{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap}
.uh h4{margin:0;font-size:19px;font-weight:800;letter-spacing:-.6px;color:var(--ink)}
.uh h4.uclick{cursor:pointer;transition:.12s}
.uh h4.uclick:hover{color:var(--accent)}
.uh h4.uclick::after{content:' ›';color:var(--ink3);font-weight:600}
.uh .oid{font:600 11px var(--num);color:var(--ink3)}
.uh .pos{margin-left:auto;font-size:12px;color:var(--ink2)}
.uh .pos b{color:var(--ink);font-weight:800}
.lead{font-size:13px;color:var(--ink2);margin:7px 0 14px;line-height:1.6}
.lead b{color:var(--ink);font-weight:700}
.shstrip{display:grid;grid-template-columns:repeat(auto-fit,minmax(124px,1fr));gap:1px;background:var(--line);
 border:1px solid var(--line);border-radius:11px;overflow:hidden;margin-bottom:15px}
.shstrip .shm{background:var(--card);padding:9px 11px}
.shstrip .l{font-size:11px;color:var(--ink3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shstrip .v{font:700 16px var(--num);letter-spacing:-.4px;margin:2px 0 4px;font-variant-numeric:tabular-nums;color:var(--ink)}
.shstrip .b{height:4px;background:var(--line2);border-radius:2px;overflow:hidden;margin-bottom:3px}
.shstrip .b i{display:block;height:100%;border-radius:2px}
.shstrip .r{font:600 11px var(--num);color:var(--ink3)}
.shstrip .r.top{color:var(--s-green);font-weight:800} .shstrip .r.bot{color:var(--s-amber);font-weight:800}
.quad{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.q{border:1px solid var(--line);border-radius:13px;padding:0 15px 13px;background:var(--c0)}
.q .cap{display:inline-flex;align-items:center;transform:translateY(-10px);font-size:11px;font-weight:800;
 letter-spacing:.02em;padding:3px 12px;border-radius:999px;border:1px solid;background:var(--card)}
.q.sc{--tone:var(--s-blue)} .q.im{--tone:var(--s-green)} .q.dm{--tone:var(--s-blue)} .q.lm{--tone:var(--s-amber)}
.q{border-color:color-mix(in srgb,var(--tone) 32%,transparent)}
.q .cap{color:var(--tone);border-color:var(--tone)}
.q ul{margin:0;padding:0;list-style:none}
.q li{display:flex;align-items:baseline;gap:8px;padding:5px 0;font-size:13px;border-bottom:1px solid var(--line2)}
.q li:last-child{border-bottom:0}
.q li .dot{width:6px;height:6px;border-radius:50%;flex:0 0 6px;background:var(--tone)}
.q li.na .dot{background:var(--s-blue)} .q li.na .n{color:var(--ink3)}
.q li .t{flex:1;color:var(--ink2)}
.q li .n{font:700 13px var(--num);white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--ink)}
.q li .rr{font:600 11px var(--num);color:var(--ink3);min-width:28px;text-align:right}
.q .note{font-size:11px;color:var(--ink2);line-height:1.6;margin-top:9px;padding-top:9px;border-top:1px dashed var(--line)}
:root{--sc:var(--s-blue);--im:var(--s-green);--dm:var(--s-blue);--lm:var(--s-amber)}
@media(max-width:1100px){.quad{grid-template-columns:1fr}}
/* 순위 비교 표 */
.rkx thead tr.g th{border-bottom:none;padding-bottom:2px;font-size:11px;letter-spacing:.02em}
.rkx thead tr.g th.hgs,.rkx thead tr.g th.hga,.rkx thead tr.g th.hgb,.rkx thead tr.g th.hgd{
 border-radius:8px 8px 0 0;font-weight:800}
.rkx thead tr.g th.hgs{background:var(--c1);color:var(--ink2)}
.rkx thead tr.g th.hga{background:var(--c1);color:var(--s-blue)}
.rkx thead tr.g th.hgb{background:var(--c1);color:var(--s-green)}
.rkx thead tr.g th.hgd{background:var(--c1);color:var(--s-blue)}
.rkx tr[data-sh]{cursor:pointer}
.rkx tr.krr td{background:var(--c1)}
.rkx tr.krr .dn{color:var(--navy);font-weight:800}
.rkx tr.me td{background:var(--c1)}
.rkx tr.me .dn{color:var(--accent);font-weight:800}
.rkb{display:inline-grid;place-content:center;width:26px;height:24px;border-radius:7px;
 font:700 12px var(--num);background:var(--c1);color:var(--ink3)}
.rkb.r1{background:var(--navy);color:var(--on-solid)}
.rkb.r2{background:var(--t-blue);color:var(--navy)}
.rkb.rl{background:var(--c1);color:var(--s-blue)}
.rkb.r1.t-im{background:var(--s-green)} .rkb.r2.t-im{background:var(--t-green);color:var(--s-green)}
.cc{font:700 10px var(--num);color:var(--ink3);background:var(--c1);padding:2px 6px;border-radius:5px}
.rkb.r1.t-dm{background:var(--s-blue)} .rkb.r2.t-dm{background:var(--c2);color:var(--s-blue)}
/* 지표 설명 팝업 */
.modal{position:fixed;inset:0;z-index:200;background:rgba(22,32,46,.42);display:none;
 align-items:center;justify-content:center;padding:24px;backdrop-filter:blur(2px)}
.modal.on{display:flex}
.modal .mbox{background:var(--card);border-radius:18px;box-shadow:0 24px 60px rgba(22,32,46,.28);
 max-width:520px;width:100%;max-height:80vh;overflow:auto;padding:22px 24px 24px;position:relative}
.modal .mx{position:absolute;top:12px;right:14px;width:28px;height:28px;border-radius:9px;
 font-size:19px;color:var(--ink3);background:transparent;line-height:1}
.modal .mx:hover{background:var(--c1);color:var(--ink)}
.modal h4{margin:0 0 5px;font-size:17px;font-weight:800;color:var(--ink)}
