 .udual2{grid-template-columns:1fr 60px 1fr}
 .ulinkw,.ulink{width:60px}
 .udual2 .ur .nm{flex:0 0 56px;font-size:11.5px}
 .udual2 .ur .bar b{font-size:10.5px}
}

/* 로그아웃 */
.rail button.lgo{color:var(--ink3);opacity:.9}
.rail button.lgo:hover{background:var(--t-red);color:var(--s-red);opacity:1}
.rail button.lgo i{font-size:16px}
.rail button.lgo.adm span::after{content:'관리자';display:block;font:800 8px var(--ui);color:var(--accent);letter-spacing:.02em;margin-top:1px}

/* ── 화면 구성(관리자) ── */
.rail button.setb{color:var(--ink3)}
.rail button.setb:hover{background:var(--accent2);color:var(--accent)}
body.vis-edit .rail button.setb{background:var(--accent-solid);color:var(--on-accent);box-shadow:var(--shl)}
body.vis-edit .ecard,body.vis-edit .xpanel,body.vis-edit .pane,body.vis-edit .rail button[data-v]{
 cursor:pointer;transition:.14s;position:relative}
body.vis-edit .ecard:hover,body.vis-edit .xpanel:hover,body.vis-edit .pane:hover{
 outline:2px dashed var(--accent);outline-offset:2px}
body.vis-edit .rail button[data-v]:hover{outline:2px dashed var(--accent);outline-offset:-2px}
.vis-off{opacity:.28;filter:grayscale(.7)}
body.vis-edit .vis-off{outline:2px solid var(--s-red);outline-offset:2px}
body.vis-edit .rail button.vis-off{outline:2px solid var(--s-red);outline-offset:-2px}
body.vis-edit .ecard.vis-off::after,body.vis-edit .xpanel.vis-off::after,body.vis-edit .pane.vis-off::after{
 content:'일반 사용자에게 안 보임';position:absolute;top:8px;right:10px;z-index:5;
 font:800 10.5px var(--ui);color:var(--on-solid);background:var(--s-red);
 padding:3px 8px;border-radius:7px;opacity:1;pointer-events:none}
.visbar{position:fixed;left:50%;bottom:20px;transform:translateX(-50%);z-index:300;
 display:flex;align-items:center;gap:13px;padding:11px 15px;border-radius:14px;
 background:var(--sel-bg);color:var(--sel-fg);box-shadow:0 14px 40px rgba(7,23,57,.34);max-width:calc(100vw - 32px)}
.visbar .vt b{font-size:13px;font-weight:800;display:block}
.visbar .vt span{font-size:11.5px;opacity:.82;display:block;margin-top:2px}
.visbar .vt span b{display:inline;font-size:11.5px}
.visbar .vn{font:700 12px var(--num);padding:5px 10px;border-radius:8px;background:var(--veil18);white-space:nowrap}
.visbar .vn b{font-size:15px}
.visbar .vb{font:800 12.5px var(--ui);padding:8px 14px;border-radius:9px;
 background:var(--veil22);color:var(--sel-fg);white-space:nowrap;transition:.13s}
.visbar .vb:hover{background:var(--veil18)}
.visbar .vb.save{background:var(--accent-solid);color:var(--on-accent)}
.visbar .vb.save:disabled{opacity:.45;cursor:default}
.vistoast{position:fixed;left:50%;bottom:92px;transform:translateX(-50%);z-index:310;
 padding:10px 18px;border-radius:11px;background:var(--s-green);color:var(--on-solid);
 font:700 13px var(--ui);box-shadow:0 10px 28px rgba(7,23,57,.3)}
.vistoast.bad{background:var(--s-red)}
@media(max-width:900px){ .visbar{flex-wrap:wrap;bottom:96px;gap:9px;padding:10px 12px} .visbar .vt{flex-basis:100%} }
